<template>
<section v-if="forecast.available" class="stock-projection" aria-label="One-year stock price projections">
  <header><div><h2>Price projection</h2><strong class="central-target">{{ money(forecast.cases[1].price,forecast.currency) }} <span>{{ pct(forecast.cases[1].return) }}</span></strong><p>{{ forecast.projectionLens==='growth_focused'?'Growth-focused central scenario':'Central scenario' }} · {{ targetDate }}</p></div><div class="upside-callout"><span>Potential upside</span><b>{{ pct(forecast.cases[2].return) }}</b><small>High scenario</small></div></header>
  <svg viewBox="0 0 900 325" role="img" :aria-label="`${run.ticker} recorded price history and conditional low, central and high endpoints`">
    <g class="projection-grid"><g v-for="tick in geometry.ticks" :key="tick.value"><line x1="25" x2="738" :y1="tick.y" :y2="tick.y"/><text x="10" :y="tick.y-6">{{ number(tick.value) }}</text></g></g>
    <polygon class="projection-fan" :points="`${geometry.reference.x},${geometry.reference.y} ${geometry.endpoints[2].x},${geometry.endpoints[2].y} ${geometry.endpoints[0].x},${geometry.endpoints[0].y}`"/>
    <path v-if="geometry.history.length>1" class="observed-line" :d="historyPath"/>
    <line class="projection-divider" x1="445" x2="445" y1="34" y2="290"/>
    <g v-for="end in geometry.endpoints" :key="end.key" :class="['projection-endpoint',end.key]" role="button" tabindex="0" :aria-label="`${labels[end.key]} scenario ${money(end.price,forecast.currency)}`" :aria-pressed="selected===end.key" @click="selected=end.key" @keydown.enter="selected=end.key" @keydown.space.prevent="selected=end.key"><line :x1="geometry.reference.x" :y1="geometry.reference.y" :x2="end.x" :y2="end.y"/><circle :cx="end.x" :cy="end.y" r="4"/><text :x="end.x+13" :y="end.y-7">{{ labels[end.key] }} {{ pct(end.return) }}</text><text class="endpoint-price" :x="end.x+13" :y="end.y+13">{{ money(end.price,forecast.currency) }}</text></g>
    <circle class="reference-dot" :cx="geometry.reference.x" :cy="geometry.reference.y" r="4"/>
    <text class="chart-section-label" x="25" y="316">Captured price history</text><text class="chart-section-label" x="465" y="316">One-year agent scenarios</text>
  </svg>
  <div class="projection-cases"><button v-for="item in forecast.cases" :key="item.key" :aria-pressed="selected===item.key" :class="{selected:selected===item.key}" @click="selected=item.key"><span>{{ labels[item.key] }}</span><b>{{ money(item.price,forecast.currency) }}</b><small>{{ pct(item.return) }}</small></button></div>
  <p class="projection-reference">Reference {{ money(forecast.reference,forecast.currency) }} · {{ sourceDate }} · {{ forecast.evidence }} evidence</p>
  <details class="projection-assumptions"><summary>{{ labels[selected] }} scenario assumptions</summary><p>{{ forecast.cases.find(c=>c.key===selected)?.reason }}</p></details>
  <p class="projection-caption">Conditional scenario endpoints; the connecting paths illustrate the range.</p>
</section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {stockProjection,projectionGeometry} from '../utils/stockResultsView.mjs'
import {money} from '../utils/stockCurrency.mjs'
const props=defineProps({run:{type:Object,required:true}})
const forecast=computed(()=>stockProjection(props.run)),geometry=computed(()=>projectionGeometry(forecast.value)),selected=ref('central')
const labels={low:'Low',central:'Central',high:'High'}
const historyPath=computed(()=>geometry.value.history.map((p,i)=>`${i?'L':'M'}${p.x},${p.y}`).join(' '))
const pct=value=>new Intl.NumberFormat('en',{style:'percent',maximumFractionDigits:1,signDisplay:'always'}).format(value)
const number=value=>value.toLocaleString('en',{maximumFractionDigits:2})
const sourceDate=computed(()=>new Date(forecast.value.asOf).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}))
const targetDate=computed(()=>new Date(forecast.value.target+'T12:00:00').toLocaleDateString(undefined,{month:'short',year:'numeric'}))
watch(()=>props.run.id,()=>{selected.value='central'})
</script>
<style scoped>
