isplay:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid var(--sr-line,#e5e9ef);margin-top:14px}.projection-cases button{display:grid;gap:4px;text-align:left;padding:14px 12px;background:none;border:0;border-bottom:2px solid transparent;color:var(--sr-ink,#18202c);cursor:pointer;font:inherit;min-width:0}.projection-cases button.selected{background:#ef762409;border-bottom-color:#ec7627}.projection-cases button>span{font-size:11px;color:var(--sr-muted,#68788b)}.projection-cases b{font-size:18px;font-weight:550;font-variant-numeric:tabular-nums}.projection-cases small{font-size:12px;color:var(--sr-muted,#68788b)}.projection-reference,.projection-caption{font-size:11px;color:var(--sr-muted,#68788b);line-height:1.6;margin:13px 0 0}.projection-caption{font-size:10px;margin-top:7px}.projection-assumptions{font-size:12px;color:var(--sr-muted,#68788b);margin-top:10px}.projection-assumptions summary{cursor:pointer}.projection-assumptions p{font-size:12px;line-height:1.8;max-width:700px}@media(max-width:650px){.central-target{font-size:28px}.central-target span{display:block;font-size:13px;margin-left:0;margin-top:5px}.upside-callout{padding-left:12px}.upside-callout b{font-size:20px}.stock-projection svg{min-height:180px}.projection-cases b{font-size:16px}.projection-cases button{padding:12px 8px}.projection-cases small{font-size:11px}}
</style>
